def reverse_sequence_operations(n, a):
    result = []
    for num in reversed(a):
        result.append(num)
        result.reverse()
    return ' '.join(map(str, result))

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:]))
    print(reverse_sequence_operations(n, a))
